// commands/remote.ts — 让本人其他设备访问引擎。引擎始终只绑 127.0.0.1，入口只有三种：
// ssh（默认，服务端零改动）/ tailscale serve / caddy（仅 vps，复用 dsh-vps 的 Caddy）
import { readFile, rm } from 'node:fs/promises';
import { hostname, userInfo } from 'node:os';
import { join } from 'node:path';
import { requireRootInVps } from '../context.js';
import { DshModelError } from '../errors.js';
import { L } from '../i18n.js';
import { loadAll, saveAll } from '../ops.js';
import { withLock } from '../state.js';
import { run, which } from '../util/exec.js';
import { atomicWrite, exists, timestamp } from '../util/fs.js';
import { bold, info, next, ok, skip } from '../util/output.js';
const CADDYFILE = '/etc/caddy/Caddyfile';
const CADDY_SNIPPET = '/etc/caddy/dsh-model.conf';
const IMPORT_LINE = `import ${CADDY_SNIPPET}`;
const DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i;
export async function remote(ctx, sub, opts) {
    requireRootInVps(ctx);
    return withLock(ctx, async () => {
        const all = await loadAll(ctx);
        if (sub === 'disable') {
            await disable(ctx, all);
            await saveAll(ctx, all);
            return 0;
        }
        if (sub !== 'enable')
            throw new DshModelError('unknown_command', L('用法：dsh-model remote enable --via ssh|tailscale|caddy / remote disable', 'Usage: dsh-model remote enable --via ssh|tailscale|caddy / remote disable'));
        const via = (opts.via ?? 'ssh');
        if (all.state.remote && all.state.remote.mode !== 'off' && all.state.remote.mode !== via)
            await disable(ctx, all);
        const port = all.config.port;
        if (via === 'ssh') {
            all.state.remote = { mode: 'ssh', files: [] };
            const target = `${ctx.env.SUDO_USER || userInfo().username}@${ctx.env.SSH_CONNECTION?.split(' ')[2] || hostname()}`;
            info(bold(L('在你自己的设备上执行（保持运行）：', 'On your own device, run (keep it open):')));
            info(`  ssh -N -L ${port}:127.0.0.1:${port} ${target}`);
            info(L(`然后在那台设备的软件里填：Base URL http://127.0.0.1:${port}/v1`, `Then in software on that device use: Base URL http://127.0.0.1:${port}/v1`));
        }
        else if (via === 'tailscale') {
            if (!(await which('tailscale')))
                throw new DshModelError('tailscale_missing', L('没找到 tailscale 命令', 'tailscale command not found'), L('先安装并登录 Tailscale', 'Install and log in to Tailscale first'));
            const r = await run('tailscale', ['serve', '--bg', `--https=${port}`, `http://127.0.0.1:${port}`]);
            if (r.code !== 0)
                throw new DshModelError('tailscale_failed', L(`tailscale serve 失败：${r.stderr.trim()}`, `tailscale serve failed: ${r.stderr.trim()}`));
            all.state.remote = { mode: 'tailscale', files: [], tailscaleHttpsPort: port };
            const dns = await run('tailscale', ['status', '--json']);
            const name = (() => {
                try {
                    return String(JSON.parse(dns.stdout).Self?.DNSName ?? '').replace(/\.$/, '');
                }
                catch {
                    return '';
                }
            })();
            ok(L('已通过 tailscale serve 开放给你的 tailnet', 'Exposed to your tailnet via tailscale serve'));
            info(L(`  Base URL：https://${name || '<本机 tailnet 域名>'}:${port}/v1`, `  Base URL: https://${name || '<this machine tailnet name>'}:${port}/v1`));
        }
        else if (via === 'caddy') {
            if (ctx.mode !== 'vps')
                throw new DshModelError('caddy_vps_only', L('caddy 方式只用于 dsh-vps 所在的服务器', 'The caddy method is only for the dsh-vps server'));
            const domain = opts.domain ?? all.config.remote.domain;
            if (!domain || !DOMAIN_RE.test(domain))
                throw new DshModelError('missing_domain', L('需要一个解析到这台服务器的域名：--domain dsh-model.example.com', 'Need a domain pointing to this server: --domain dsh-model.example.com'));
            await enableCaddy(ctx, all, domain);
            all.config.remote.domain = domain;
            ok(L(`已通过 Caddy 开放：https://${domain}/v1`, `Exposed via Caddy: https://${domain}/v1`));
        }
        else {
            throw new DshModelError('unknown_remote', L(`不支持的方式：${via}`, `Unsupported method: ${via}`));
        }
        all.config.remote.mode = via;
        await saveAll(ctx, all);
        next(L('为每台设备单独发一把 key：dsh-model key add <设备名>（丢了就 key revoke）', 'Issue one key per device: dsh-model key add <device> (revoke it if lost)'));
        return 0;
    });
}
async function enableCaddy(ctx, all, domain) {
    if (!(await exists(CADDYFILE)))
        throw new DshModelError('caddy_missing', L(`没找到 ${CADDYFILE}`, `${CADDYFILE} not found`));
    const original = await readFile(CADDYFILE, 'utf8');
    const backup = join(ctx.paths.backups, `Caddyfile.${timestamp()}`);
    await atomicWrite(backup, original);
    await atomicWrite(CADDY_SNIPPET, `# Generated by dsh-model. 由 dsh-model 生成\n${domain} {\n\treverse_proxy 127.0.0.1:${all.config.port}\n}\n`, { mode: 0o644 });
    const hasImport = original.split('\n').some((l) => l.trim() === IMPORT_LINE);
    if (!hasImport)
        await atomicWrite(CADDYFILE, original.replace(/\n*$/, '\n') + IMPORT_LINE + '\n', { mode: 0o644 });
    const v = await run('caddy', ['validate', '--config', CADDYFILE, '--adapter', 'caddyfile']);
    if (v.code !== 0) {
        await atomicWrite(CADDYFILE, original, { mode: 0o644 });
        await rm(CADDY_SNIPPET, { force: true });
        throw new DshModelError('caddy_invalid', L(`Caddy 配置校验失败，已回滚：${v.stderr.trim().slice(-300)}`, `Caddy config validation failed; rolled back: ${v.stderr.trim().slice(-300)}`));
    }
    const r = await run('systemctl', ['reload', 'caddy']);
    if (r.code !== 0)
        throw new DshModelError('caddy_reload_failed', L(`Caddy 重载失败：${r.stderr.trim()}`, `Caddy reload failed: ${r.stderr.trim()}`));
    all.state.remote = { mode: 'caddy', files: [CADDY_SNIPPET], caddyImportLine: hasImport ? undefined : IMPORT_LINE, caddyfile: CADDYFILE };
}
export async function disable(ctx, all) {
    const r = all.state.remote;
    if (!r || r.mode === 'off') {
        skip(L('远程访问本来就是关闭的', 'Remote access is already off'));
        return;
    }
    if (r.mode === 'tailscale' && r.tailscaleHttpsPort) {
        await run('tailscale', ['serve', `--https=${r.tailscaleHttpsPort}`, 'off']);
    }
    if (r.mode === 'caddy') {
        for (const f of r.files)
            await rm(f, { force: true });
        if (r.caddyImportLine && r.caddyfile && (await exists(r.caddyfile))) {
            const text = await readFile(r.caddyfile, 'utf8');
            const kept = text.split('\n').filter((l) => l.trim() !== r.caddyImportLine).join('\n');
            await atomicWrite(r.caddyfile, kept, { mode: 0o644 });
        }
        await run('systemctl', ['reload', 'caddy']);
    }
    all.state.remote = { mode: 'off', files: [] };
    all.config.remote.mode = 'off';
    ok(L('已关闭远程访问', 'Remote access disabled'));
}
